import{_ as t,o,c as r,a6 as n}from"./chunks/framework.QBF2cGGQ.js";const c=JSON.parse('{"title":"01 · LLM 基础","description":"","frontmatter":{},"headers":[],"relativePath":"guide/01-llm-basics.md","filePath":"guide/01-llm-basics.md","lastUpdated":1793329740000}'),i={name:"guide/01-llm-basics.md"};function p(a,s,l,e,g,d){return o(),r("div",null,[...s[0]||(s[0]=[n('<h1 id="_01-·-llm-基础" tabindex="-1">01 · LLM 基础 <a class="header-anchor" href="#_01-·-llm-基础" aria-label="Permalink to &quot;01 · LLM 基础&quot;">​</a></h1><blockquote><p><strong>投入权重：10%</strong> · 不必会训练，但必须能解释&quot;模型为什么这样表现&quot;。 这一层的作用是让你出问题时知道往哪查，而不是瞎调 prompt。</p></blockquote><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>能做到这三件事就算过关：一、别人问&quot;为什么它记不住我刚说的话&quot;，你能答出上下文窗口与注意力衰减；二、让你估算一次请求的成本，你能给出数量级；三、遇到输出格式错乱，你知道该改 prompt、换 structured output、还是上约束解码。</p><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><ul><li><strong>Transformer 整体结构</strong> <span class="prio prio-must">必须</span> — Encoder-Decoder 与 Decoder-only 的区别；当前主流全是 Decoder-only，理解这一点才能理解&quot;为什么是自回归生成&quot;。</li><li><strong>Self-Attention 计算过程</strong> <span class="prio prio-must">必须</span> — Q/K/V 的来历，<code>softmax(QKᵀ/√d)V</code> 每一步在做什么。能手推一遍就够，不必背公式。</li><li><strong>Multi-Head Attention</strong> <span class="prio prio-imp">重要</span> — 多头的意义是让不同头关注不同关系（语法/指代/位置）。理解它才能理解&quot;注意力可视化&quot;类工具在展示什么。</li><li><strong>位置编码</strong> <span class="prio prio-imp">重要</span> — 绝对位置编码 → 相对位置 → RoPE（当前主流）→ ALiBi。这条演化线直接关系到长上下文外推能力。</li><li><strong>RMSNorm 与残差连接</strong> <span class="prio prio-opt">选学</span> — 为什么用 RMSNorm 不用 LayerNorm，残差如何让深层网络可训练。</li><li><strong>FFN / 前馈层</strong> <span class="prio prio-opt">选学</span> — 参数量主要在这里（约占三分之二），MoE 也是在这里做稀疏化。</li><li><strong>因果掩码</strong> <span class="prio prio-imp">重要</span> — 为什么生成时看不到未来 token。理解它才能理解&quot;为什么不能反向生成&quot;、为什么流式输出天然是单向的。</li><li><strong>KV Cache</strong> <span class="prio prio-must">必须</span> — 推理加速的核心：缓存历史 K/V 避免重复计算。它同时是显存占用的主要来源，直接决定并发数。部署章节会反复用到。</li><li><strong>MoE 混合专家</strong> <span class="prio prio-imp">重要</span> — 用稀疏激活换参数量，DeepSeek / Qwen 都在用。理解&quot;总参数 vs 激活参数&quot;的区别，否则会被宣传数字误导。</li><li><strong>Prefill 与 Decode 两阶段</strong> <span class="prio prio-must">必须</span> — 推理分成两段：<strong>Prefill</strong> 一次性并行处理全部输入（算力密集，决定 TTFT）；<strong>Decode</strong> 逐 token 生成（显存带宽密集，决定 TPOT）。<strong>这两个阶段的瓶颈完全不同，优化手段也不同</strong>——Prefill 靠加算力，Decode 靠减少显存读写。</li><li><strong>Chunked Prefill</strong> <span class="prio prio-imp">重要</span> — 超长输入会长时间占住 GPU 导致其他请求 TTFT 爆炸。切成小块穿插执行，牺牲一点吞吐换延迟稳定。</li><li><strong>算力密集 vs 带宽密集</strong> <span class="prio prio-imp">重要</span> — 长输入短输出（RAG、分类）是 Prefill 主导，看算力；短输入长输出（写作、推理）是 Decode 主导，看显存带宽。<strong>这个判断直接决定你该买什么卡、怎么批处理</strong>。</li></ul><h2 id="模型类型" tabindex="-1">模型类型 <a class="header-anchor" href="#模型类型" aria-label="Permalink to &quot;模型类型&quot;">​</a></h2><p>不是所有&quot;模型&quot;都是聊天模型。<strong>选错类型是新手最常见的低级错误</strong>——比如拿生成模型做分类、拿 embedding 模型做问答。</p><ul><li><strong>Base（基座模型）</strong> <span class="prio prio-imp">重要</span> — 只会续写，不会对话。适合做微调起点，不适合直接用。</li><li><strong>Instruction / Chat（指令模型）</strong> <span class="prio prio-must">必须</span> — 经过 SFT/RLHF，会听指令。<strong>日常调用 99% 用这个</strong>。</li><li><strong>Reasoning（推理模型）</strong> <span class="prio prio-must">必须</span> — 先想再答（o 系列、DeepSeek-R1 系）。<strong>优势在数学/代码/多步逻辑，劣势是慢和贵</strong>。不要拿它做简单分类。</li><li><strong>推理预算（Reasoning Budget）</strong> <span class="prio prio-imp">重要</span> — 推理模型可以控制&quot;想多久&quot;。<strong>简单任务给低预算能省一大笔</strong>，难题给高预算。这是 2024 年之后新增的重要成本杠杆。</li><li><strong>过度思考的代价</strong> <span class="prio prio-imp">重要</span> — 推理模型对简单问题会绕远路，反而更差。<strong>要按任务难度路由</strong>，不是全都上最强模型。</li><li><strong>Embedding 模型</strong> <span class="prio prio-must">必须</span> — 输出向量，用于检索/聚类/去重。<strong>它不能生成文字</strong>，混用是硬伤。</li><li><strong>Reranker（重排模型）</strong> <span class="prio prio-must">必须</span> — Cross-Encoder 结构，输入 query+doc 输出相关性分数。比向量检索准但慢，<strong>只用在召回后的精排</strong>。</li><li><strong>VLM（视觉语言模型）</strong> <span class="prio prio-must">必须</span> — 图文输入。详见 <a href="/ai-eng-roadmap/guide/23-multimodal">23 · 多模态</a>。</li><li><strong>Speech 模型</strong> <span class="prio prio-imp">重要</span> — ASR（语音转文字）/ TTS（文字转语音）/ 端到端语音对话。三类完全不同。</li><li><strong>多模态统一模型</strong> <span class="prio prio-opt">选学</span> — 一个模型同时处理文/图/音/视频。能力全面但单项常不如专用模型。</li><li><strong>Guard / 审核模型</strong> <span class="prio prio-imp">重要</span> — 专门做内容安全分类，比用大模型判断便宜几十倍。</li><li><strong>怎么记住</strong> <span class="prio prio-must">必须</span> — 一句话：<strong>生成用 chat/reasoning，检索用 embedding，精排用 reranker，看图用 VLM，安全用 guard。</strong> 面试问&quot;你会用哪些模型&quot;，按这五类答。</li></ul><h2 id="必要的数学" tabindex="-1">必要的数学 <a class="header-anchor" href="#必要的数学" aria-label="Permalink to &quot;必要的数学&quot;">​</a></h2><p>不用会推导，但<strong>看到这些词不能懵</strong>。面试官问&quot;余弦相似度和点积什么区别&quot;，答不上来说明 RAG 是抄来的。</p><ul><li><strong>向量与点积</strong> <span class="prio prio-must">必须</span> — 点积衡量方向和长度。<strong>内积检索（<code>&lt;#&gt;</code>）比余弦快但受向量长度影响</strong>，归一化后就等价了。</li><li><strong>范数（L2）</strong> <span class="prio prio-must">必须</span> — 向量长度。归一化 = 除以范数，让所有向量长度变 1，此时点积 = 余弦。</li><li><strong>余弦相似度</strong> <span class="prio prio-must">必须</span> — 只看方向不看长度，范围 -1~1。<strong>文本 embedding 基本都用它</strong>。</li><li><strong>欧氏距离（L2 距离）</strong> <span class="prio prio-must">必须</span> — 直线距离。归一化向量下，欧氏距离和余弦单调对应（<code>d² = 2 - 2cos</code>）。</li><li><strong>为什么 embedding 要归一化</strong> <span class="prio prio-must">必须</span> — 不归一化时，长文本的向量范数更大，会系统性地&quot;更相似&quot;。<strong>很多检索效果差就是漏了这一步</strong>。</li><li><strong>Softmax</strong> <span class="prio prio-must">必须</span> — 把分数变成概率分布。temperature 就是在 softmax 前除以 T。<strong>理解这一点就理解了 temperature 的本质</strong>。</li><li><strong>交叉熵（Cross-Entropy）</strong> <span class="prio prio-imp">重要</span> — 语言模型的训练损失就是它。困惑度（perplexity）= exp(交叉熵)。</li><li><strong>梯度下降</strong> <span class="prio prio-opt">选学</span> — 沿梯度反方向更新参数。学习率、batch size、梯度累积的关系，微调时会用到。</li><li><strong>矩阵乘法</strong> <span class="prio prio-imp">重要</span> — Transformer 里几乎全是它。<strong>理解了&quot;矩阵乘是算力瓶颈&quot;就理解了为什么 GPU 重要</strong>。</li><li><strong>精度类型</strong> <span class="prio prio-imp">重要</span> — FP32 / FP16 / BF16 / FP8 / INT8 / INT4 的位数与动态范围差异。<strong>BF16 比 FP16 动态范围大，训练更稳</strong>；推理量化见 <a href="/ai-eng-roadmap/guide/06-inference">06 · 推理</a>。</li></ul><h2 id="tokenizer" tabindex="-1">Tokenizer <a class="header-anchor" href="#tokenizer" aria-label="Permalink to &quot;Tokenizer&quot;">​</a></h2><ul><li><strong>BPE / WordPiece / SentencePiece</strong> <span class="prio prio-imp">重要</span> — 分词算法差异；为什么&quot;数不清 strawberry 有几个 r&quot;是分词问题不是智力问题。</li><li><strong>中文 token 效率</strong> <span class="prio prio-must">必须</span> — 同一段中文在不同 tokenizer 下的 token 数可能差 1.5 倍，直接决定成本。选型时要拿自己的真实语料实测，不要看宣传。</li><li><strong>token 与字符的换算</strong> <span class="prio prio-imp">重要</span> — 中文约 1 字 ≈ 1~1.5 token，英文约 1 词 ≈ 1.3 token。粗算用它，精确算用 tiktoken 类库。<strong>这是经验值，不是精确公式，务必用自己语料校准。</strong></li><li><strong>特殊 token 与对话模板</strong> <span class="prio prio-imp">重要</span> — BOS/EOS、system/user/assistant 标记。自己拼 prompt 时拼错模板会显著掉效果，尤其是本地模型。</li><li><strong>token 计费逻辑</strong> <span class="prio prio-must">必须</span> — 输入/输出分开计价，输出通常贵 2~4 倍；缓存命中价更低。做成本模型必须懂。</li></ul><h2 id="训练流程-了解即可" tabindex="-1">训练流程（了解即可） <a class="header-anchor" href="#训练流程-了解即可" aria-label="Permalink to &quot;训练流程（了解即可）&quot;">​</a></h2><ul><li><strong>预训练目标</strong> <span class="prio prio-imp">重要</span> — next token prediction。理解这一点就理解&quot;模型本质是概率续写器&quot;，很多幻觉由此而来。</li><li><strong>SFT 监督微调</strong> <span class="prio prio-imp">重要</span> — 用指令-回答对做监督学习，让基座模型学会&quot;听话&quot;。第 05 章会深入。</li><li><strong>RLHF：奖励模型 + PPO</strong> <span class="prio prio-opt">选学</span> — 人类偏好 → 奖励模型 → 强化学习。理解它才能理解&quot;对齐税&quot;和&quot;过度拒答&quot;。</li><li><strong>DPO / ORPO / KTO</strong> <span class="prio prio-imp">重要</span> — 跳过奖励模型的偏好优化，工程上更简单，微调阶段会用到。</li><li><strong>Scaling Law</strong> <span class="prio prio-opt">选学</span> — 参数/数据/算力的幂律关系。用途：判断&quot;这事该换更大模型还是改架构&quot;。</li><li><strong>蒸馏</strong> <span class="prio prio-imp">重要</span> — 大模型生成数据教小模型，是降本主力手段，也是把能力搬进私有模型的主要路径。</li></ul><h2 id="采样与生成参数" tabindex="-1">采样与生成参数 <a class="header-anchor" href="#采样与生成参数" aria-label="Permalink to &quot;采样与生成参数&quot;">​</a></h2><ul><li><strong>temperature</strong> <span class="prio prio-must">必须</span> — 控制分布锐度。事实性任务调低（0~0.3），创意任务调高。注意：temperature=0 也不保证完全可复现。</li><li><strong>top_p（nucleus sampling）</strong> <span class="prio prio-must">必须</span> — 按累积概率截断。业界惯例是调 temperature 或 top_p 之一，不要同时大改，否则难以归因。</li><li><strong>top_k</strong> <span class="prio prio-imp">重要</span> — 只从概率最高的 k 个里采样。约束更强，常用于本地小模型。</li><li><strong>repetition / frequency / presence penalty</strong> <span class="prio prio-imp">重要</span> — 抑制复读。过高会导致语句破碎，调参要小步（0.05 级别）。</li><li><strong>stop sequences</strong> <span class="prio prio-imp">重要</span> — 提前终止，省钱且能控制格式。多轮 Agent 里常用。</li><li><strong>logit_bias</strong> <span class="prio prio-opt">选学</span> — 对特定 token 加权/降权。强制或禁止某些词时有用。</li><li><strong>seed 与可复现性</strong> <span class="prio prio-imp">重要</span> — 部分厂商支持固定种子，但跨版本、跨硬件仍不可复现。别把测试建立在&quot;必然一致&quot;上。</li><li><strong>beam search vs sampling</strong> <span class="prio prio-opt">选学</span> — 前者求最优序列（翻译类），后者求多样性（对话类）。API 场景基本只用采样。</li></ul><h2 id="上下文窗口" tabindex="-1">上下文窗口 <a class="header-anchor" href="#上下文窗口" aria-label="Permalink to &quot;上下文窗口&quot;">​</a></h2><ul><li><strong>上下文窗口的含义</strong> <span class="prio prio-must">必须</span> — 一次请求能塞入的最大 token 数（输入与输出共享）。不是越大越好，成本与延迟随长度线性上升。</li><li><strong>Lost in the Middle</strong> <span class="prio prio-must">必须</span> — 关键信息放在长上下文中段时召回显著下降。所以&quot;把文档全塞进去&quot;通常不如精准检索。这是 RAG 存在的理由之一。</li><li><strong>长上下文外推</strong> <span class="prio prio-opt">选学</span> — YaRN / NTK 插值等把短训练模型拉到长上下文的技术，效果有衰减，宣称的窗口长度不等于有效长度。</li><li><strong>上下文预算分配</strong> <span class="prio prio-must">必须</span> — system / 检索内容 / 历史对话 / 输出预留，四者抢同一个池子。必须显式分配，不能任其膨胀。</li><li><strong>上下文膨胀的隐性成本</strong> <span class="prio prio-imp">重要</span> — 每轮都带全部历史，成本是 O(n²) 增长。长会话必须做裁剪或摘要。</li></ul><h2 id="能力与局限" tabindex="-1">能力与局限 <a class="header-anchor" href="#能力与局限" aria-label="Permalink to &quot;能力与局限&quot;">​</a></h2><ul><li><strong>幻觉的机制与分类</strong> <span class="prio prio-must">必须</span> — 事实性幻觉（编事实）与忠实性幻觉（不忠于给定材料）。后者才是 RAG 要解决的核心，前者靠检索也难以完全消除。</li><li><strong>知识截止</strong> <span class="prio prio-must">必须</span> — 模型不知道训练后的事。任何时效性需求必须外挂检索。</li><li><strong>算术与精确计数</strong> <span class="prio prio-must">必须</span> — 弱项。涉及数字就让模型输出表达式交给代码算，别让它心算。</li><li><strong>指令遵循 vs 格式遵循</strong> <span class="prio prio-must">必须</span> — 能听懂要求 ≠ 能稳定输出合法 JSON。后者需要 structured output 或约束解码。</li><li><strong>多语言能力不均衡</strong> <span class="prio prio-imp">重要</span> — 中文强的模型英文可能弱，反之亦然。跨语言场景要分别测。</li><li><strong>多模态能力边界</strong> <span class="prio prio-imp">重要</span> — 图像理解对文字密集图（截图/表格）弱，对自然图像强。需要 OCR 兜底。</li><li><strong>自我认知不可靠</strong> <span class="prio prio-imp">重要</span> — 问模型&quot;你是什么版本&quot;经常答错。版本信息只能从 API 响应或配置里拿。</li><li><strong>长链推理的误差累积</strong> <span class="prio prio-imp">重要</span> — 推理步数越多，中间步骤出错被放大的概率越高。这是&quot;为什么要把复杂任务拆给代码&quot;的原因。</li></ul><h2 id="模型族与选型" tabindex="-1">模型族与选型 <a class="header-anchor" href="#模型族与选型" aria-label="Permalink to &quot;模型族与选型&quot;">​</a></h2><ul><li><p><strong>GPT 系列</strong> <span class="prio prio-must">必须</span> — 综合能力强，生态与工具链最全，价格中高。</p></li><li><p><strong>Claude 系列</strong> <span class="prio prio-must">必须</span> — 长文本与代码/写作强，工具调用稳定，适合 Agent。</p></li><li><p><strong>Gemini 系列</strong> <span class="prio prio-must">必须</span> — 超长上下文与多模态强，价格有优势。</p></li><li><p><strong>Qwen 系列</strong> <span class="prio prio-must">必须</span> — 中文与开源生态最完整，尺寸齐全，国内部署首选。</p></li><li><p><strong>DeepSeek 系列</strong> <span class="prio prio-must">必须</span> — 性价比极高，开源权重可自部署，推理能力强。</p></li><li><p><strong>Llama / Mistral 系列</strong> <span class="prio prio-imp">重要</span> — 海外开源基座，微调生态最成熟。</p></li><li><p><strong>国产合规模型（GLM / 豆包 / 混元 / 文心）</strong> <span class="prio prio-imp">重要</span> — 有备案、可开票、数据不出境，ToB 项目常是硬性要求。</p></li><li><p><strong>开源 vs 闭源的取舍</strong> <span class="prio prio-must">必须</span> — 开源换数据主权与成本可控，闭源换能力上限与免运维。判断依据是&quot;数据能不能出境&quot;和&quot;量级够不够摊薄运维成本&quot;。</p></li><li><p><strong>模型选型 12 项指标</strong> <span class="prio prio-must">必须</span> — 别只看&quot;跑分&quot;。做一张打分表，逐项填：</p><table tabindex="0"><thead><tr><th>#</th><th>指标</th><th>怎么测</th></tr></thead><tbody><tr><td>1</td><td>任务准确率</td><td>自己的评测集跑分，不看公开榜</td></tr><tr><td>2</td><td>中文能力</td><td>中文语料实测，很多模型英文强中文弱</td></tr><tr><td>3</td><td>指令/格式遵循</td><td>让它输出严格 JSON 100 次，数失败几次</td></tr><tr><td>4</td><td>工具调用准确率</td><td>给 10 个工具，测选择与参数正确率</td></tr><tr><td>5</td><td>上下文有效长度</td><td>不是标称长度，测&quot;第 50k token 还能答对吗&quot;</td></tr><tr><td>6</td><td>TTFT 与 TPOT</td><td>实测 P50/P95，不是看宣传</td></tr><tr><td>7</td><td>单位成本</td><td>输入/输出分开算，算到&quot;每千次任务&quot;</td></tr><tr><td>8</td><td>限流与配额</td><td>RPM/TPM 上限，够不够你的峰值</td></tr><tr><td>9</td><td>可用性 SLA</td><td>历史故障率、有没有多区域</td></tr><tr><td>10</td><td>数据条款</td><td>会不会拿去训练、零留存选项</td></tr><tr><td>11</td><td>合规资质</td><td>备案、发票、能否私有化</td></tr><tr><td>12</td><td>版本稳定性</td><td>会不会静默升级，能不能锁版本</td></tr></tbody></table><p><strong>前 4 项决定能不能用，后 8 项决定能不能长期用。</strong> 面试时能报出其中几项实测数字，可信度立刻不一样。</p></li><li><p><strong>多模型策略</strong> <span class="prio prio-imp">重要</span> — 贵模型做难任务，便宜模型做简单任务，路由分流。这是降本最有效的手段之一。</p></li><li><p><strong>版本更新与能力漂移</strong> <span class="prio prio-imp">重要</span> — 厂商静默更新模型会改变行为。必须锁定版本号（如果支持）并保留回归测试。</p></li></ul>',24)])])}const m=t(i,[["render",p]]);export{c as __pageData,m as default};
